package com.melsuhaimi.sleepapp.bootstrap;

public final class CheckpointContract {
    public static final String APPLICATION_ID = "com.melsuhaimi.sleepapp.bootstrap";
    public static final String SCREEN_TEXT = "Sleep App AI Harness Probe";

    private CheckpointContract() {}
}

package com.melsuhaimi.sleepapp.bootstrap;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import org.junit.Test;

public final class CheckpointContractTest {
    @Test
    public void applicationIdentityIsStable() {
        assertEquals("com.melsuhaimi.sleepapp.bootstrap", CheckpointContract.APPLICATION_ID);
        assertEquals("Sleep App AI Harness Probe", CheckpointContract.SCREEN_TEXT);
        assertFalse(CheckpointContract.APPLICATION_ID.isBlank());
    }
}
